import hashlib
import json
from pathlib import Path
import statistics
import sys
from time import perf_counter

import torch
from rich.console import Console

from bio_inspired_nanochat.synaptic import _scripted_scan_rng


@torch.jit.script
def assume_normal_draw(
    valid: torch.Tensor,
    generator: torch.Generator,
    width: int,
    fraction: float,
) -> tuple[torch.Tensor, torch.Tensor, bool]:
    batch, heads, queries, topk = valid.shape
    uniform = torch.jit.annotate(list[torch.Tensor], [])
    noise = torch.jit.annotate(list[torch.Tensor], [])
    for _ in range(queries):
        uniform.append(torch.rand((batch, heads, 1), dtype=torch.float32,
                                  device=valid.device, generator=generator))
        samples = torch.randn((batch, heads, 1, width), dtype=torch.float32,
                              device=valid.device, generator=generator)
        noise.append(samples[..., :topk])
    uniforms = torch.cat(uniform, dim=2)
    # Accept only if the incumbent takes every normal-draw branch on this tape.
    draw = (uniforms < fraction) & valid.any(dim=-1)
    accepted = bool(draw.reshape(batch * heads, queries).any(dim=0).all())
    return uniforms.reshape(batch * heads, queries), torch.cat(noise, dim=2), accepted


def incumbent(valid, rng, width, fraction, cap):
    return _scripted_scan_rng(valid, rng, *valid.shape, width, fraction, cap)


def grouped(valid, rng, width, fraction, cap, chunk=8):
    if cap <= 0:
        return (*incumbent(valid, rng, width, fraction, cap), 0, 0)
    uniforms, noises = [], []
    accepted, rejected = 0, 0
    for block in valid.split(chunk, dim=2):
        snapshot = rng.get_state()
        try:
            uniform, noise, success = assume_normal_draw(block, rng, width, fraction)
        except Exception:
            rng.set_state(snapshot)
            raise
        if success:
            accepted += 1
        else:
            rng.set_state(snapshot)
            uniform, noise = incumbent(block, rng, width, fraction, cap)
            rejected += 1
        uniforms.append(uniform)
        noises.append(noise)
    return torch.cat(uniforms, dim=1), torch.cat(noises, dim=2), accepted, rejected


def bits_equal(a, b):
    return (a.dtype == b.dtype and a.shape == b.shape
            and torch.equal(a.contiguous().view(torch.uint8), b.contiguous().view(torch.uint8)))


def digest(tensor):
    array = tensor.detach().contiguous().view(torch.uint8).cpu().numpy()
    return hashlib.sha256(array.tobytes()).hexdigest()


def run_case(device, case, valid, before, width, frac, cap, timed):
    generator = torch.Generator(device=device)

    def execute(candidate, state):
        generator.set_state(state)
        if candidate:
            output = grouped(valid, generator, width, frac, cap)
        else:
            output = incumbent(valid, generator, width, frac, cap)
        return output, generator.get_state()

    checks = []
    state = before
    timing_states = []
    for _ in range(8):
        timing_states.append(state)
        original, expected_state = execute(False, state)
        candidate, returned_state = execute(True, state)
        checks.append({
            "uniform_exact": bits_equal(original[0], candidate[0]),
            "noise_exact": bits_equal(original[1], candidate[1]),
            "end_rng_exact": torch.equal(expected_state, returned_state),
            "rng_before": digest(state), "rng_after": digest(expected_state),
            "accepted": candidate[2], "fallback": candidate[3],
        })
        state = expected_state

    measurements = []
    if timed and all(row["uniform_exact"] and row["noise_exact"] and row["end_rng_exact"] for row in checks):
        for pair in range(8):
            elapsed = {}
            for selected in (False, True) if pair % 2 == 0 else (True, False):
                torch.cuda.synchronize(device)
                start = perf_counter()
                for call in range(128):
                    execute(selected, timing_states[call % len(timing_states)])
                torch.cuda.synchronize(device)
                elapsed["candidate" if selected else "reference"] = perf_counter() - start
            measurements.append(elapsed)
    return {
        "case": case, "valid_sha256": digest(valid), "geometry": list(valid.shape),
        "fraction": frac, "cap": cap, "checks": checks,
        "pairs_128_calls": measurements,
        "median_ratio": (statistics.median(row["candidate"] / row["reference"] for row in measurements)
                         if measurements else None),
    }


def main(input_dir, report):
    observations = {}
    for rank in (0, 1):
        device = torch.device("cuda", rank)
        torch.cuda.set_device(device)
        payload = torch.load(input_dir / f"rank{rank}.pt", map_location=device, weights_only=True)
        args = payload["args"]
        valid, frac, width, cap = args[11], args[16], args[17], args[18]
        before = payload["before_rng"].cpu()
        no_key = valid.clone()
        no_key[:, :, 0, :] = False
        exact_all = torch.ones_like(valid[:, :, :17, :])
        with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
            observations[str(rank)] = [
                run_case(device, "saved D1", valid, before, width, frac, cap, True),
                run_case(device, "forced fallback", no_key, before, width, frac, cap, False),
                run_case(device, "non-divisible query count", exact_all, before, width, frac, cap, False),
                run_case(device, "zero cap", valid, before, width, frac, 0, False),
            ]
        for row in observations[str(rank)]:
            Console().print_json(data={
                "rank": rank, "case": row["case"], "median_ratio": row["median_ratio"],
                "blocks": [[r["accepted"], r["fallback"]] for r in row["checks"]],
                "exact": all(r["uniform_exact"] and r["noise_exact"] and r["end_rng_exact"]
                             for r in row["checks"]),
            })
    with report.open("x", encoding="utf-8") as stream:
        json.dump(observations, stream, indent=2, sort_keys=True)
        stream.write("\n")
    for rows in observations.values():
        assert all(row["uniform_exact"] and row["noise_exact"] and row["end_rng_exact"]
                   for case in rows for row in case["checks"])
        assert all(row["fallback"] > 0 for row in rows[1]["checks"])
        assert all(row["accepted"] + row["fallback"] == 3 for row in rows[2]["checks"])
        assert any(row["accepted"] > 0 for row in rows[0]["checks"])


if __name__ == "__main__":
    main(*(Path(value) for value in sys.argv[1:]))

